import pandas as pd,numpy as np
from scipy.optimize import least_squares
fs=['A_vref_op1','A_vref_op3','A_gentrip_op1','A_load_op2','A_line_op3','A_amb_op1']
D={f:pd.read_csv('train/%s.csv'%f).iloc[::10] for f in fs}
def sim(p,d):
    kp,Tw,a1,b1,c1,Tq,kw=p
    t=d.time_s.values;dt=t[1]-t[0]
    V=d.voltage_pu.values;th=d.bus_angle_rad.values;vs=d.voltage_setpoint_pu.values
    P0,Q0=d.active_power_pu.values[0],d.reactive_power_pu.values[0]
    x=0;q=0;P=[];Q=[]
    for i in range(len(t)):
        w=(th[i]-x)/Tw
        P.append(P0-kp*w/377); Q.append(Q0+q+c1*(V[i]-V[0])+kw*w/377)
        x+=dt/Tw*(th[i]-x)
        q+=dt/Tq*(a1*(vs[i]-V[0])+b1*(V[i]-V[0])-q)
    return np.array(P),np.array(Q)
def res(p,ret=False):
    r=[]
    for f,d in D.items():
        P,Q=sim(p,d);r+=[P-d.active_power_pu.values,Q-d.reactive_power_pu.values]
    return np.concatenate(r)
s=least_squares(res,[17,.03,1,0,1,.3,0],x_scale=[5,.03,1,1,1,.3,1],bounds=([0,.01,-50,-50,-50,.01,-50],[80,5,50,50,50,10,50]))
print(s.x,np.sqrt(np.mean(s.fun**2)))
for f,d in D.items():
    P,Q=sim(s.x,d);print(f,np.std(P-d.active_power_pu),np.std(Q-d.reactive_power_pu),np.std(d.active_power_pu),np.std(d.reactive_power_pu))
